import{_ as n,o as t,c as s,a4 as e}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"路由层选型与事件驱动设计","description":"","frontmatter":{"title":"路由层选型与事件驱动设计","date":"2026-05-28T00:00:00.000Z"},"headers":[],"relativePath":"posts/路由层选型与事件驱动设计.md","filePath":"posts/路由层选型与事件驱动设计.md"}'),i={name:"posts/路由层选型与事件驱动设计.md"};function l(o,a,d,p,r,h){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="路由层选型与事件驱动设计" tabindex="-1">路由层选型与事件驱动设计 <a class="header-anchor" href="#路由层选型与事件驱动设计" aria-label="Permalink to &quot;路由层选型与事件驱动设计&quot;">​</a></h1><blockquote><p>从 route-agent.py 到 n8n 到 Dify 到 LangGraph 的技术路径 2026-05-28 ~ 2026-06-08</p></blockquote><hr><h2 id="起点-route-agent-py" tabindex="-1">起点：route-agent.py <a class="header-anchor" href="#起点-route-agent-py" aria-label="Permalink to &quot;起点：route-agent.py&quot;">​</a></h2><p>最早的路由层是一个自建 Python HTTP 服务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>route-agent.py（端口 8765）</span></span>
<span class="line"><span>  ├── /register — Agent 注册（HWND + session）</span></span>
<span class="line"><span>  ├── /event    — 接收 commit 事件 → 决策 → 注入</span></span>
<span class="line"><span>  └── /status   — 查询工作间状态</span></span></code></pre></div><p><strong>问题：</strong></p><ul><li>Python 脚本，改逻辑要改代码</li><li>没有可视化界面</li><li>状态管理靠内存（重启丢失）</li><li>功能单一，往复杂走要加很多端点</li></ul><hr><h2 id="第一站-n8n" tabindex="-1">第一站：n8n <a class="header-anchor" href="#第一站-n8n" aria-label="Permalink to &quot;第一站：n8n&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>git commit → post-commit hook</span></span>
<span class="line"><span>  → curl POST n8n webhook</span></span>
<span class="line"><span>    → n8n Code 节点解析 payload</span></span>
<span class="line"><span>      → 条件分支（REVIEW-PASS / REVIEW-FAIL）</span></span>
<span class="line"><span>        → Code 节点调 inject 脚本</span></span></code></pre></div><p><strong>n8n 的优势：</strong></p><ul><li>Webhook 节点原生支持 HTTP 接收</li><li>Code 节点内写 JavaScript / Python</li><li>条件分支可视化</li><li>自带日志和重试</li></ul><p><strong>实际 n8n 搭建成果：</strong></p><ul><li>两个原子节点工作流：<code>fn_launch_claude</code> + <code>fn_send_to_window</code></li><li>模板化：<code>launch_agent.json</code> + <code>send_to_window.json</code></li><li>全链路验证通过：commit → webhook → Code 节点 → inject → agent 窗口收到</li></ul><p><strong>遇到的问题：</strong></p><ul><li>Windows 上的 ExecuteCommand 节点阻塞子进程 — 改用 Code 节点 + execSync</li><li>n8n 在 Docker 里无法直接访问宿主机窗口 — 需要 host.docker.internal 桥接</li><li>汉化包版本必须精确匹配 n8n 版本（2.23.4）</li></ul><hr><h2 id="第二站-dify-评估" tabindex="-1">第二站：Dify 评估 <a class="header-anchor" href="#第二站-dify-评估" aria-label="Permalink to &quot;第二站：Dify 评估&quot;">​</a></h2><p><strong>提出用 Dify 原因：</strong></p><ul><li>可视化编排（比 n8n 更直观）</li><li>内置 LLM 节点（不需要外挂 Hermes）</li><li>自带日志和状态追踪</li></ul><p><strong>否决原因：</strong></p><ul><li>Dify 也在 Docker 里，同样面临跨网络问题</li><li>需要 host.docker.internal 桥接</li><li>LLM 节点用不上（路由逻辑不是 LLM 决策）</li><li><strong>多了一层 Docker，没有解决 n8n 解决不了的问题</strong></li></ul><hr><h2 id="第三站-langgraph-评估" tabindex="-1">第三站：LangGraph 评估 <a class="header-anchor" href="#第三站-langgraph-评估" aria-label="Permalink to &quot;第三站：LangGraph 评估&quot;">​</a></h2><p><strong>优势：</strong></p><ul><li>本地 Python 进程，不需要 Docker 网络</li><li>直接调文件 API、注入脚本</li><li><code>graph_state</code> 天然适合状态追踪</li><li>条件边 = 路由决策</li></ul><p><strong>否决原因：</strong></p><ul><li>纯代码，没有可视化界面</li><li>跟 route-agent.py 本质是同一类东西（Python 脚本）</li><li>n8n 已经验证了 Webhook 链路可用</li><li>路由层不值得再用一个框架</li></ul><hr><h2 id="最终形态-n8n" tabindex="-1">最终形态：n8n <a class="header-anchor" href="#最终形态-n8n" aria-label="Permalink to &quot;最终形态：n8n&quot;">​</a></h2><p>回到 n8n，但去掉 Windows 注入层：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>n8n（Windows 路由层）</span></span>
<span class="line"><span>  ↓ Webhook 接收 commit 事件</span></span>
<span class="line"><span>  ↓ Code 节点解析 payload</span></span>
<span class="line"><span>  ↓ 条件分支路由</span></span>
<span class="line"><span>  ↓ wsl tmux send-keys 注入</span></span></code></pre></div><h3 id="三层分离" tabindex="-1">三层分离 <a class="header-anchor" href="#三层分离" aria-label="Permalink to &quot;三层分离&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>职责</th><th>技术选型</th></tr></thead><tbody><tr><td>路由层</td><td>n8n</td><td>事件接收、解析、决策、注入</td><td>n8n Webhook + Code</td></tr><tr><td>会话层</td><td>WSL</td><td>Agent 持久化、命令注入</td><td>tmux</td></tr><tr><td>协议层</td><td>文件系统</td><td>共享状态、行为规范</td><td>STATUS.md + SKILL.md</td></tr></tbody></table><hr><h2 id="事件链路总图" tabindex="-1">事件链路总图 <a class="header-anchor" href="#事件链路总图" aria-label="Permalink to &quot;事件链路总图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Agent（写完）</span></span>
<span class="line"><span>  ↓ 追加 STATUS.md</span></span>
<span class="line"><span>  ↓ git add &amp;&amp; git commit -m &quot;[CC-WSxxx] ...&quot;</span></span>
<span class="line"><span>  ↓ post-commit hook</span></span>
<span class="line"><span>  ↓ notify-agent.sh（curl POST）</span></span>
<span class="line"><span>n8n webhook（http://localhost:5679/webhook/agent-loop）</span></span>
<span class="line"><span>  ↓ Code 节点解析 payload 获取 author/message</span></span>
<span class="line"><span>  ↓ 条件分支：</span></span>
<span class="line"><span>    ├─ REVIEW-PASS → notify Hermes → 标记完成</span></span>
<span class="line"><span>    ├─ CC commit → tmux send-keys -t codex &quot;/review-ws&quot;</span></span>
<span class="line"><span>    └─ Codex REVIEW-FAIL → tmux send-keys -t cc &quot;/fix-ws&quot;</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Agent 窗口收到指令 → 读 STATUS.md → 继续循环</span></span></code></pre></div><hr><h2 id="选型对比总结" tabindex="-1">选型对比总结 <a class="header-anchor" href="#选型对比总结" aria-label="Permalink to &quot;选型对比总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>可视化</th><th>跨 Docker</th><th>注入能力</th><th>最终</th></tr></thead><tbody><tr><td>route-agent.py</td><td>❌</td><td>✅ 原生</td><td>✅</td><td>❌ 被替代</td></tr><tr><td>n8n</td><td>✅</td><td>❌ 需要桥接</td><td>✅（Code 节点）</td><td>✅ 最终选型</td></tr><tr><td>Dify</td><td>✅</td><td>❌ 需要桥接</td><td>✅</td><td>❌ 多余层</td></tr><tr><td>LangGraph</td><td>❌</td><td>✅ 原生</td><td>✅</td><td>❌ 跟 route-agent 同级</td></tr></tbody></table><hr><h2 id="经验" tabindex="-1">经验 <a class="header-anchor" href="#经验" aria-label="Permalink to &quot;经验&quot;">​</a></h2><ol><li><strong>别用框架解决路由问题</strong> — 路由就是一个条件分支 + inject，n8n 够用了</li><li><strong>三层分离才能解耦</strong> — 路由层、会话层、协议层各自可独立替换</li><li><strong>可视化不是必须的，但 debug 时很香</strong> — n8n 的执行日志比 Python print 强多了</li></ol>`,44)])])}const u=n(i,[["render",l]]);export{g as __pageData,u as default};
